import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { 
  ArrowLeft, 
  ExternalLink, 
  Clock, 
  User, 
  Tag,
  Loader2,
  AlertCircle 
} from 'lucide-react';
import { format } from 'date-fns';
import { zhCN } from 'date-fns/locale';

const NewsDetail = () => {
  const { id } = useParams();
  const [news, setNews] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchNewsDetail = async () => {
      try {
        setLoading(true);
        setError(null);

        const response = await fetch(`/api/news/${id}`);
        const data = await response.json();

        if (data.success) {
          setNews(data.data);
        } else {
          throw new Error(data.error || '获取新闻详情失败');
        }
      } catch (err) {
        console.error('获取新闻详情失败:', err);
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    if (id) {
      fetchNewsDetail();
    }
  }, [id]);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="w-8 h-8 animate-spin text-blue-600 mr-2" />
        <span className="text-gray-600">加载详情中...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="text-center py-12">
        <AlertCircle className="w-12 h-12 text-red-500 mx-auto mb-4" />
        <h3 className="text-lg font-medium text-gray-900 mb-2">加载失败</h3>
        <p className="text-gray-600 mb-4">{error}</p>
        <Link
          to="/"
          className="inline-flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
        >
          <ArrowLeft className="w-4 h-4 mr-2" />
          返回首页
        </Link>
      </div>
    );
  }

  if (!news) {
    return (
      <div className="text-center py-12">
        <h3 className="text-lg font-medium text-gray-900 mb-2">新闻不存在</h3>
        <Link
          to="/"
          className="inline-flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
        >
          <ArrowLeft className="w-4 h-4 mr-2" />
          返回首页
        </Link>
      </div>
    );
  }

  const getCategoryColor = (category) => {
    const colors = {
      'AI新闻': 'bg-blue-100 text-blue-700',
      'AI框架': 'bg-green-100 text-green-700',
      '新算法': 'bg-purple-100 text-purple-700',
      '新思路': 'bg-yellow-100 text-yellow-700',
      '新工具': 'bg-pink-100 text-pink-700',
    };
    return colors[category] || 'bg-gray-100 text-gray-700';
  };

  return (
    <article className="max-w-4xl mx-auto">
      {/* 面包屑导航 */}
      <div className="flex items-center space-x-2 text-sm text-gray-500 mb-6">
        <Link to="/" className="hover:text-blue-600 transition-colors">
          首页
        </Link>
        <span>/</span>
        <span className={getCategoryColor(news.category)}>
          {news.category}
        </span>
      </div>

      {/* 返回按钮 */}
      <Link
        to="/"
        className="inline-flex items-center text-blue-600 hover:text-blue-700 mb-6 transition-colors"
      >
        <ArrowLeft className="w-4 h-4 mr-2" />
        返回列表
      </Link>

      {/* 文章内容 */}
      <div className="bg-white rounded-lg shadow-sm border border-gray-200">
        {/* 头部信息 */}
        <div className="p-8 border-b border-gray-200">
          <div className="flex items-center space-x-2 mb-4">
            <span className={`px-3 py-1 rounded-full text-sm font-medium ${getCategoryColor(news.category)}`}>
              {news.category}
            </span>
            <span className="text-sm text-gray-500">•</span>
            <span className="text-sm text-gray-500">{news.source}</span>
          </div>

          <h1 className="text-3xl font-bold text-gray-900 mb-6 leading-tight">
            {news.title}
          </h1>

          <div className="flex items-center space-x-6 text-sm text-gray-500">
            <div className="flex items-center">
              <Clock className="w-4 h-4 mr-2" />
              {format(new Date(news.publishedAt), 'yyyy年MM月dd日 HH:mm', { locale: zhCN })}
            </div>

            {news.author && (
              <div className="flex items-center">
                <User className="w-4 h-4 mr-2" />
                {news.author}
              </div>
            )}
          </div>
        </div>

        {/* 主图 */}
        {news.imageUrl && (
          <div className="p-8 border-b border-gray-200">
            <img
              src={news.imageUrl}
              alt={news.title}
              className="w-full max-h-96 object-cover rounded-lg"
              onError={(e) => {
                e.target.parentElement.style.display = 'none';
              }}
            />
          </div>
        )}

        {/* 内容 */}
        <div className="p-8">
          {news.description && (
            <div className="prose max-w-none mb-8">
              <p className="text-lg text-gray-700 leading-relaxed">
                {news.description}
              </p>
            </div>
          )}

          {/* 操作按钮 */}
          <div className="flex items-center space-x-4 pt-6 border-t border-gray-200">
            <a
              href={news.url}
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
            >
              <ExternalLink className="w-4 h-4 mr-2" />
              阅读原文
            </a>

            <button className="inline-flex items-center px-6 py-3 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors">
              <Tag className="w-4 h-4 mr-2" />
              收藏
            </button>
          </div>
        </div>
      </div>

      {/* 相关推荐 */}
      <div className="mt-8">
        <h2 className="text-xl font-semibold text-gray-900 mb-4">相关推荐</h2>
        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
          <p className="text-gray-600">
            暂未实现相关推荐功能
          </p>
        </div>
      </div>
    </article>
  );
};

export default NewsDetail;
